#include "gtest/gtest.h"

#include <cstring>
#include <sstream>
#include <string>
#include <variant>

#include "cryptonote_basic/cryptonote_basic.h"
#include "string_tools.h"
#include "serialization/binary_archive.h"

using namespace cryptonote;

namespace {

// Pinned `wire_hex` from gate2_serve_credit_kat_v1.json (synthetic_minimal_path).
constexpr const char* GATE2_KAT_WIRE_HEX =
  "";

} // namespace

TEST(archival_serve_credit, gate2_kat_vin_deserializes)
{
  std::string wire;
  ASSERT_TRUE(epee::string_tools::parse_hexstr_to_binbuff(GATE2_KAT_WIRE_HEX, wire));
  ASSERT_FALSE(wire.empty());
  EXPECT_EQ(static_cast<uint8_t>(wire[0]), 0x02u);

  txin_v vin;
  binary_archive<false> iar({reinterpret_cast<const uint8_t*>(wire.data()), wire.size()});
  ASSERT_TRUE(::do_serialize(iar, vin));
  ASSERT_TRUE(std::holds_alternative<txin_archival_serve_credit_response>(vin));

  const auto& resp = std::get<txin_archival_serve_credit_response>(vin);
  EXPECT_EQ(resp.shard_id, 42u);
  EXPECT_EQ(resp.settlement_epoch, 7u);
  EXPECT_EQ(resp.leaf_index_in_segment, 1234u);
  EXPECT_EQ(resp.path.c1_layers.size(), 1u);
  EXPECT_EQ(resp.path.c1_layers[0].size(), 4u);
  EXPECT_EQ(resp.path.c2_layers.size(), 2u);
  EXPECT_EQ(resp.path.c2_layers[0].size(), 8u);
  EXPECT_FALSE(resp.hybrid_signature.empty());

  archival_leaf_bytes expected_leaf{};
  memset(expected_leaf.data, 0x33, sizeof(expected_leaf.data));
  EXPECT_EQ(resp.leaf_bytes, expected_leaf);

  crypto::hash expected_p{}, expected_rk{};
  memset(&expected_p, 0x11, sizeof(expected_p));
  memset(&expected_rk, 0x22, sizeof(expected_rk));
  EXPECT_EQ(resp.p_canonical_id, expected_p);
  EXPECT_EQ(resp.segment_subroot_rk, expected_rk);
}

TEST(archival_serve_credit, txin_roundtrip_matches_kat_bytes)
{
  std::string wire;
  ASSERT_TRUE(epee::string_tools::parse_hexstr_to_binbuff(GATE2_KAT_WIRE_HEX, wire));

  txin_v vin;
  binary_archive<false> iar({reinterpret_cast<const uint8_t*>(wire.data()), wire.size()});
  ASSERT_TRUE(::do_serialize(iar, vin));

  std::ostringstream oss;
  binary_archive<true> oar(oss);
  ASSERT_TRUE(::do_serialize(oar, vin));

  const std::string roundtrip = oss.str();
  EXPECT_EQ(roundtrip, wire);
}
